};

export default async function Page({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  const params = await searchParams;
  // Preserve existing operator bookmarks without putting their credential into
  // the public landing page or its outbound source links.
  if (params.key) {
    const query = new URLSearchParams();
    for (const [name, value] of Object.entries(params)) {
      if (Array.isArray(value)) value.forEach(item => query.append(name, item));
      else if (value !== undefined) query.append(name, value);
    }
    redirect(`/board?${query.toString()}`);
  }
  return <Landing />;
}

"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { CodeGraphView, type ViewGraph } from "../components/CodeGraphView";
import { key, zone } from "../zones/client";
import s from "../zones/zones.module.css";

// Teammate workspace: LEFT Team Memory (doubts + escalation) and RIGHT Code
// Navigator (graph). CENTER is visible but locked unless the server says otherwise.
// ← / → (or click) selects; selection is sent as a low-privilege focus event.

type Me = { participant?: { name: string }; role?: string; zones?: Record<string, { allowed: boolean; reason?: string }>; snapshot?: { label: string; pinnedSha: string; repository: string }; error?: string };
type Mem = { kind: string; speak: string; offerEscalation: boolean; sources: { kind: string; label: string }[]; question: string; provisional: { text: string }[]; pendingTicket?: { id: string } | null };
type GA = { explanation: string[]; match: string; seed: { label: string; path: string; line: number } | null; subgraph: { nodes: string[] }; graph: ViewGraph; sha: string; repository: string };
type Ticket = { id: string; question: string; state: string; answer?: { statement: string; conditions?: string; approvedBy: string; decisionVersion: number } };

export default function Team() {
  const [me, setMe] = useState<Me | null>(null);
  const [focus, setFocus] = useState<"team_memory" | "code_navigator">("team_memory");
  const seq = useRef(0);
  const [q, setQ] = useState("Who owns the codebase graph agent?");
  const [mem, setMem] = useState<Mem | null>(null);
  const [sent, setSent] = useState<string | null>(null);
  const [cq, setCq] = useState("where do we read back before saying saved");
  const [ga, setGa] = useState<GA | null>(null);
  const [error, setError] = useState("");
  const [inbox, setInbox] = useState<{ answered: Ticket[]; pending: Ticket[] }>({ answered: [], pending: [] });

  useEffect(() => { zone<Me>("me").then((r) => setMe(r.data)).catch(() => setError("Cannot connect. Try again.")); }, []);
  const select = useCallback((z: "team_memory" | "code_navigator" | "leader_desk") => {
    seq.current = Math.max(Date.now(), seq.current + 1);
    void zone("focus", { zone: z, provider: "manual", seq: seq.current }).catch(() => setError("Focus could not be saved. Try again."));
    if (z !== "leader_desk") setFocus(z);
  }, []);
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).tagName === "INPUT") return;
      if (e.key === "ArrowLeft") select("team_memory");
      if (e.key === "ArrowRight") select("code_navigator");
      if (e.key === "ArrowUp") select("leader_desk");
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [select]);
  // Answers from the leader arrive here, also after a reconnect.
  useEffect(() => {
    const poll = () => zone<{ answered: Ticket[]; pending: Ticket[] }>("deliveries").then((r) => r.status === 200 && r.data.answered && setInbox({ answered: r.data.answered, pending: r.data.pending })).catch(() => setError("Answers could not refresh. Retrying…"));
    poll(); const id = setInterval(poll, 3000); return () => clearInterval(id);
  }, []);

  const ask = async () => {
    setSent(null); setError(""); setMem(null);
    try { const r = await zone<Mem>("memory_ask", { question: q });
      if (r.status !== 200 || !r.data.kind) throw new Error(r.data.error ?? "Memory unavailable");
      setMem(r.data);
    } catch (e) { setError((e as Error).message); }
  };
  const escalate = async () => {
    try { const r = await zone<{ ticket: Ticket }>("ticket_create", { question: mem?.question ?? q, confirmed: true, idempotency_key: key() });
      setSent(r.data.ticket ? `Sent to the leader as ${r.data.ticket.id}. I won't guess; you'll see the answer here.` : r.data.error ?? "not sent");
    } catch { setError("Question could not be sent. Try again."); }
  };
  const navigate = async () => {
    setError(""); setGa(null);
    try { const r = await zone<GA>("code_graph_query", { question: cq });
      if (r.status !== 200 || !r.data.graph || !r.data.subgraph) throw new Error(r.data.error ?? "Code graph unavailable");
      setGa(r.data);
    } catch (e) { setError((e as Error).message); }
  };

  if (me?.error) return <main className={s.page}><p>Open this page from your personal session link (<code>npm run session:issue</code>). {me.error}</p></main>;

  return (
    <main className={s.page}>
      <div className={s.top}>
        <h1 className={s.title}>Kaam Ki Baat · {me?.participant?.name ?? "…"}</h1>
        <div className={s.meta}>{me?.snapshot && <><span className={s.badge}>{me.snapshot.label}</span> {me.snapshot.repository} @ {me.snapshot.pinnedSha.slice(0, 7)}</>}</div>
      </div>
      {error && <p className={s.bad} role="alert">{error}</p>}
      <div className={s.zones} role="tablist" aria-label="Agents (← ↑ →)">
        <button className={`${s.zbtn} ${focus === "team_memory" ? s.zbtnOn : ""}`} onClick={() => select("team_memory")}><div className={s.label}>← left</div>Team Memory</button>
        <button className={`${s.zbtn} ${s.lock}`} onClick={() => select("leader_desk")} title={me?.zones?.leader_desk?.reason}><div className={s.label}>↑ front · locked</div>Leader Desk</button>
        <button className={`${s.zbtn} ${focus === "code_navigator" ? s.zbtnOn : ""}`} onClick={() => select("code_navigator")}><div className={s.label}>right →</div>Code Navigator</button>
      </div>

      <div className={s.grid}>
        <section className={`${s.card} ${focus === "team_memory" ? s.active : ""}`}>
          <div className={s.label}>Team Memory</div>
          <div className={s.h}>What did we decide?</div>
          <div className={s.row}>
            <input className={s.input} value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === "Enter" && ask()} aria-label="Ask Team Memory" />
            <button className={`${s.btn} ${s.primary}`} onClick={ask}>Ask</button>
          </div>
          {mem && (
            <div className={s.answer}>
              <div className={mem.kind === "confirmed" ? s.ok : mem.kind === "conditional" ? s.warn : s.bad}>● {mem.kind.replace("_", " ")}</div>
              <div style={{ marginTop: 6 }}>{mem.speak}</div>
              <div className={s.src}>{mem.sources.map((x, i) => <span key={i}>{x.kind} · {x.label}</span>)}{mem.provisional.map((p, i) => <span key={`p${i}`} className={s.warn}>live (provisional) · {p.text}</span>)}</div>
              {mem.offerEscalation && !mem.pendingTicket && !sent && <button className={s.btn} style={{ marginTop: 12 }} onClick={escalate}>Yes, ask the leader</button>}
              {sent && <p className={s.meta} style={{ marginTop: 10 }}>{sent}</p>}
            </div>
          )}
          <div className={s.list}>
            {inbox.answered.map((t) => (
              <div key={t.id} className={s.item}>
                <div className={s.ok}>Leader answered · v{t.answer?.decisionVersion}</div>
                <div>“{t.question}” → <b>{t.answer?.statement}</b>{t.answer?.conditions ? `, on condition that ${t.answer.conditions}` : ""}</div>
                {t.state !== "acknowledged" && <button className={s.btn} style={{ marginTop: 8 }} onClick={() => { void zone("delivery_ack", { ticket_id: t.id }).then(r => { if (r.status !== 200) setError(r.data.error ?? "Acknowledgement failed"); }).catch(() => setError("Acknowledgement failed. Try again.")); }}>Got it</button>}
              </div>
            ))}
            {inbox.pending.map((t) => <div key={t.id} className={s.item}><span className={s.warn}>Pending with the leader</span> · {t.question}</div>)}
          </div>
        </section>

        <section className={`${s.card} ${focus === "code_navigator" ? s.activeR : ""}`}>
          <div className={s.label}>Code Navigator · graph of this repo</div>
          <div className={s.h}>Where is it in the code?</div>
          <div className={s.row}>
            <input className={s.input} value={cq} onChange={(e) => setCq(e.target.value)} onKeyDown={(e) => e.key === "Enter" && navigate()} aria-label="Ask Code Navigator" />
            <button className={`${s.btn} ${s.primary}`} onClick={navigate}>Find</button>
          </div>
          {ga ? <CodeGraphView graph={ga.graph} highlight={ga.subgraph.nodes} height={360} /> : <p className={s.meta}>Ask to load the authorized snapshot graph. Static imports and call links are hints; check the pinned source.</p>}
          {ga && (
            <>
              {ga.seed && <a className={s.meta} href={`https://github.com/${ga.repository}/blob/${ga.sha}/${ga.seed.path}#L${ga.seed.line}`} target="_blank" rel="noreferrer">{ga.seed.path}:{ga.seed.line} @ {ga.sha.slice(0, 7)} ↗ · <span className={ga.match === "confirmed" ? s.ok : s.warn}>{ga.match}</span></a>}
              <ol className={s.steps}>{ga.explanation.map((l, i) => <li key={i}>{l.replace(/^\d+\.\s*/, "")}</li>)}</ol>
            </>
          )}
        </section>
      </div>
    </main>
  );
}

"use client";
// Browser helper for /api/zones/*. The session token comes from the link the
// operator generates (`npm run session:issue`) as #t=<token>, then lives in
// sessionStorage. Role and permissions are decided by the server, never here.
export function sessionToken(): string {
  if (typeof window === "undefined") return "";
  const m = window.location.hash.match(/t=([A-Za-z0-9_-]+)/);
  if (m) { try { sessionStorage.setItem("kkb_session", m[1]); } catch { /* private mode */ } history.replaceState(null, "", window.location.pathname); }
  try { return m?.[1] ?? sessionStorage.getItem("kkb_session") ?? ""; } catch { return m?.[1] ?? ""; }
}
export async function zone<T = Record<string, unknown>>(action: string, body: Record<string, unknown> = {}): Promise<{ status: number; data: T & { ok?: boolean; error?: string } }> {
  const res = await fetch(`/api/zones/${action}`, { method: "POST", headers: { "content-type": "application/json", authorization: `Session ${sessionToken()}` }, body: JSON.stringify(body) });
  return { status: res.status, data: await res.json() };
}
export const b64u = (buf: ArrayBuffer) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
export const fromB64u = (s: string) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4)), (c) => c.charCodeAt(0));
export const key = () => (crypto.randomUUID?.() ?? String(Math.random()).slice(2)).replace(/-/g, "");

// Development-time custom-function configuration. This does not create an agent
// or place a call. Generated credentials belong only in data/private/.
type Property = { type: string; description: string; enum?: string[] };

export function buildBolnaTools(baseUrl: string, toolKey: string) {
  const url = new URL(baseUrl);
  if (url.protocol !== "https:" || url.username || url.password || url.search || url.hash || url.pathname !== "/") {
    throw new Error("Bolna callbacks require an HTTPS origin without credentials, path, query or fragment");
  }
  if (toolKey.length < 32 || /\s/.test(toolKey)) throw new Error("KKB_TOOL_KEY must be a long, nonempty server key");
  const definitions: Array<{ name: string; description: string; properties: Record<string, Property>; required: string[] }> = [
    {
      name: "get_my_brief",
      description: "Call at the start of the conversation. Read the returned speak field as the brief; never invent meeting, owner or code facts.",
      properties: {}, required: [],
    },
    {
      name: "get_task_evidence",
      description: "Use for follow-up evidence. find searches code, locate gives the file/function/test, verify checks PR and exact-SHA CI. Use only task IDs returned by the backend.",
      properties: {
        task_id: { type: "string", description: "Authorized task ID returned by get_my_brief." },
        focus: { type: "string", description: "Evidence specialist requested by the caller.", enum: ["find", "locate", "verify"] },
        question: { type: "string", description: "The caller's evidence question in their own words." },
      }, required: ["task_id", "focus", "question"],
    },
    {
      name: "get_changes",
      description: "Read saved status changes for this caller since an ISO timestamp. This does not refresh GitHub or re-read a meeting.",
      properties: { since: { type: "string", description: "ISO 8601 timestamp to compare saved task updates against." } }, required: ["since"],
    },
    {
      name: "record_task_update",
      description: "Only after the caller explicitly confirms a task and status. Reuse the same idempotency_key for retries of that update. Say saved only if saved is true and readBack is present; otherwise speak the failure.",
      properties: {
        task_id: { type: "string", description: "Authorized task ID returned by the backend." },
        status: { type: "string", description: "Confirmed task status. reported_done is the caller's report, not verified completion.", enum: ["not_started", "in_progress", "blocked", "reported_done"] },
        confirmed: { type: "boolean", description: "True only after the caller confirms this exact update." },
        idempotency_key: { type: "string", description: "Unique key of at least 8 characters for this update; keep identical on retries." },
      }, required: ["task_id", "status", "confirmed", "idempotency_key"],
    },
  ];
  return definitions.map(({ name, description, properties, required }) => ({
    name, description,
    parameters: {
      type: "object",
      properties: { call_token: { type: "string", description: "Private per-call context variable. Supplied in user_data and the prompt; never ask the caller or speak it." }, ...properties },
      required: ["call_token", ...required],
      additionalProperties: false,
    },
    key: "custom_task",
    value: {
      method: "POST",
      url: `${url.origin}/api/tools/${name}`,
      api_token: `Bearer ${toolKey}`,
      headers: { "Content-Type": "application/json" },
      param: Object.fromEntries(["call_token", ...Object.keys(properties)].map((key) => [key, `%(${key})s`])),
    },
  }));
}

import type { CheckRecord, PullRequestRecord } from "../contracts";

// Read-only GitHub REST adapter for ONE authorized repository.
// Token is optional for public repos (GITHUB_TOKEN raises rate limits).

export interface GitHubClient {
  pullRequest(number: number): Promise<PullRequestRecord>;
  checksFor(sha: string): Promise<CheckRecord[]>;
}

export class GitHubRequestError extends Error {
  constructor(
    readonly status: number,
    readonly rateLimited: boolean,
    readonly retryAfterSeconds?: number,
    readonly rateLimitReset?: string,
  ) {
    super(rateLimited
      ? `GitHub rate limit (${status})${retryAfterSeconds != null ? `; retry after ${retryAfterSeconds}s` : ""}${rateLimitReset ? `; resets at ${rateLimitReset}` : ""}`
      : `GitHub request failed (${status}); check repository access and credentials`);
    this.name = "GitHubRequestError";
  }
}

export function githubClient(repository: string, token = process.env.GITHUB_TOKEN, fetchImpl: typeof fetch = fetch): GitHubClient {
  if (!/^[A-Za-z0-9-]+\/[A-Za-z0-9_.-]+$/.test(repository) || [".", ".."].includes(repository.split("/")[1])) throw new Error("repository must be owner/name");
  const base = `https://api.github.com/repos/${repository}`;
  const get = async (url: string) => {
    const res = await fetchImpl(url, {
      headers: { Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      signal: AbortSignal.timeout(15_000),
    });
    if (!res.ok) {
      // Only inspect the message to classify secondary limits. Never echo the
      // provider body, which may contain private repository/account details.
      const body = await res.json().catch(() => ({})) as { message?: string };
      const retry = res.headers.get("retry-after");
      const reset = res.headers.get("x-ratelimit-reset");
      const rateLimited = res.status === 429 || (res.status === 403 && (
        res.headers.get("x-ratelimit-remaining") === "0" || retry != null || (typeof body?.message === "string" && /rate limit/i.test(body.message))
      ));
      const retryAfter = retry != null && /^\d+$/.test(retry) ? Number(retry) : undefined;
      const resetMs = reset != null && /^\d+$/.test(reset) ? Number(reset) * 1000 : NaN;
      const resetAt = Number.isFinite(resetMs) && !Number.isNaN(new Date(resetMs).getTime()) ? new Date(resetMs).toISOString() : undefined;
      throw new GitHubRequestError(res.status, rateLimited, rateLimited ? retryAfter : undefined, rateLimited ? resetAt : undefined);
    }
    return { body: await res.json() as any, link: res.headers.get("link") };
  };
  const pages = async <T>(endpoint: string, select: (body: any) => T[]): Promise<T[]> => {
    const resource = `${base}${endpoint}`;
    let url: string | undefined = `${resource}?per_page=100`;
    const seen = new Set<string>();
    const records: T[] = [];
    while (url) {
      // Follow pagination only within this exact resource. Never send the
      // token to a different host, repository, PR, or commit from a Link header.
      const parsed = new URL(url);
      if (parsed.origin !== "https://api.github.com" || parsed.pathname !== new URL(resource).pathname || parsed.username || parsed.password || seen.has(url)) {
        throw new Error("GitHub returned unsafe or repeated pagination; evidence is incomplete");
      }
      seen.add(url);
      const { body, link } = await get(url);
      const items = select(body);
      if (!Array.isArray(items)) throw new Error("GitHub returned invalid paginated evidence");
      records.push(...items);
      url = link?.match(/<([^>]+)>;\s*rel="next"/)?.[1];
    }
    return records;
  };
  return {
    async pullRequest(number) {
      if (!Number.isSafeInteger(number) || number < 1) throw new Error("PR number must be a positive integer");
      const { body: pr } = await get(`${base}/pulls/${number}`);
      const files = await pages<{ filename: string }>(`/pulls/${number}/files`, (body) => body);
      // GitHub caps the files endpoint at 3,000. An incomplete list must not
      // become a snapshot that silently misses the relevant code.
      if (typeof pr.changed_files === "number" && files.length !== pr.changed_files) {
        throw new Error(`GitHub PR #${number} file evidence is incomplete (${files.length}/${pr.changed_files})`);
      }
      return {
        kind: "pr",
        id: `pr:${number}`,
        repository,
        number,
        title: pr.title,
        state: pr.merged_at ? "merged" : pr.state === "open" ? "open" : "closed_unmerged",
        headSha: pr.head.sha,
        mergedSha: pr.merge_commit_sha && pr.merged_at ? pr.merge_commit_sha : undefined,
        changedFiles: files.map((f) => f.filename),
        url: pr.html_url,
      };
    },
    async checksFor(sha) {
      if (!/^[a-fA-F0-9]{7,40}$/.test(sha)) throw new Error("checks require a commit SHA");
      const checks = await pages<any>(`/commits/${sha}/check-runs`, (body) => body.check_runs);
      // skipped / neutral runs carry no verdict about the code: drop them rather than call them failures.
      return checks.filter((c) => !(c.status === "completed" && ["skipped", "neutral"].includes(c.conclusion))).map((c) => ({
        kind: "check" as const,
        id: `check:${c.id}`,
        repository,
        commitSha: c.head_sha ?? sha,
        name: c.name,
        conclusion: c.status !== "completed" ? "pending" : c.conclusion === "success" ? "success" : c.conclusion === "cancelled" ? "cancelled" : "failure", // failure | timed_out | action_required
        url: c.html_url,
      }));
    },
  };
}

import path from "node:path";
import type { EvidenceSnapshot } from "../contracts";
import { contentHash, safeSourcePath, type CodeGraph } from "../evidence/code-graph";

const record = (v: unknown): Record<string, unknown> => v !== null && typeof v === "object" && !Array.isArray(v) ? v as Record<string, unknown> : {};

// NetworkX node-link JSON from Graphify's code-only extractor. The extraction
// root must contain ONLY the snapshot's pinned code files, not the working tree.
export function importGraphify(raw: unknown, snapshot: EvidenceSnapshot, scanRoot: string, version: string): CodeGraph {
  const data = record(raw), meta = record(data.graph);
  const edges = data.links ?? data.edges;
  if (!Array.isArray(data.nodes) || !Array.isArray(edges) || data.nodes.length > 50_000 || edges.length > 200_000) throw new Error("Unsupported or oversized Graphify export");
  const files = new Map(snapshot.files.map((f) => [f.path, f.content]));
  const nodes: CodeGraph["nodes"] = [];
  const ids = new Set<string>();
  for (const value of data.nodes) {
    const n = record(value);
    if (n.file_type !== "code" || typeof n.source_file !== "string" || !n.source_file) continue;
    const source = path.isAbsolute(n.source_file) ? path.relative(scanRoot, n.source_file) : n.source_file.replace(/^\.\//, "");
    if (!safeSourcePath(source) || !files.has(source)) continue;
    const location = typeof n.source_location === "string" ? /^L(\d+)(?:-L?\d+)?$/.exec(n.source_location) : null;
    const line = location ? Number(location[1]) : 0;
    if (typeof n.id !== "string" || !n.id || ids.has(n.id) || typeof n.label !== "string" || !n.label || n.label.length > 200 || !Number.isSafeInteger(line) || line < 1 || line > files.get(source)!.split("\n").length) continue;
    ids.add(n.id);
    nodes.push({ id: n.id, label: n.label, path: source, line });
  }
  if (!nodes.length) throw new Error("Graphify returned no usable code locations");
  const normalized: CodeGraph["edges"] = [];
  for (const value of edges) {
    const e = record(value);
    if (typeof e.source !== "string" || typeof e.target !== "string" || !ids.has(e.source) || !ids.has(e.target) || typeof e.relation !== "string" || !/^[a-z_]{1,40}$/.test(e.relation) || (e.confidence !== "EXTRACTED" && e.confidence !== "INFERRED")) continue;
    normalized.push({ source: e.source, target: e.target, relation: e.relation, confidence: e.confidence });
  }
  return { format: "kkb-graphify-v1", repository: snapshot.repository, commitSha: snapshot.pinnedSha,
    builtAt: new Date().toISOString(), graphifyVersion: version,
    sourceSchemaVersion: typeof meta.schema_version === "number" || typeof meta.schema_version === "string" ? meta.schema_version : undefined,
    fileHashes: Object.fromEntries([...new Set(nodes.map((n) => n.path))].map((p) => [p, contentHash(files.get(p)!)])), nodes, edges: normalized };
}

import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
import type { EvidenceSnapshot, Participant } from "../contracts";
import type { CallSession, EventStore } from "../store/event-store";

// Identity is established server-side (D-009). The model never chooses who the
// caller is; Bolna only forwards the opaque per-call token we issued.

export const hashToken = (t: string) => createHash("sha256").update(t).digest("hex");

export async function issueCallSession(
  store: EventStore,
  input: Omit<CallSession, "callId" | "tokenHash" | "expiresAt"> & { ttlMinutes?: number },
): Promise<{ token: string; session: CallSession }> {
  const token = randomBytes(24).toString("base64url");
  const session: CallSession = {
    callId: `call_${randomBytes(6).toString("hex")}`,
    tokenHash: hashToken(token),
    participantId: input.participantId,
    meetingIds: input.meetingIds,
    repository: input.repository,
    consentRecordedBy: input.consentRecordedBy,
    scenario: input.scenario,
    expiresAt: new Date(Date.now() + (input.ttlMinutes ?? 60) * 60_000).toISOString(),
  };
  await store.append({ type: "call_session", at: new Date().toISOString(), session });
  return { token, session };
}

export interface Caller {
  session: CallSession;
  participant: Participant;
  taskIds: ReadonlySet<string>;
}

export type AuthResult = { ok: true; caller: Caller } | { ok: false; status: 401 | 403; reason: string };

/** Server key check for every runtime tool request (Authorization: Bearer). */
export function checkServerKey(header: string | null, expected: string | undefined): boolean {
  if (!expected || !header?.startsWith("Bearer ")) return false;
  const a = Buffer.from(header.slice(7));
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

export async function resolveCaller(
  store: EventStore,
  snapshot: EvidenceSnapshot,
  token: unknown,
  now = new Date(),
): Promise<AuthResult> {
  if (typeof token !== "string" || token.length < 16) return { ok: false, status: 401, reason: "missing call token" };
  const session = await store.findCallByTokenHash(hashToken(token));
  if (!session) return { ok: false, status: 401, reason: "unknown call token" };
  if (new Date(session.expiresAt) < now) return { ok: false, status: 401, reason: "call token expired" };
  if (!session.consentRecordedBy) return { ok: false, status: 403, reason: "no consent recorded" };
  if (session.repository !== snapshot.repository) return { ok: false, status: 403, reason: "repository not authorized for this call" };
  const participant = snapshot.participants.find((p) => p.id === session.participantId);
  if (!participant) return { ok: false, status: 403, reason: "participant not in authorized snapshot" };
  // A task is visible only if the participant holds it AND its meeting is authorized for both the call and the person.
  const taskIds = new Set(
    snapshot.tasks
      .filter((t) => participant.taskIds.includes(t.id))
      .filter((t) => session.meetingIds.includes(t.meetingId) && participant.meetingIds.includes(t.meetingId))
      .map((t) => t.id),
  );
  return { ok: true, caller: { session, participant, taskIds } };
}

// Code graph for the Code Navigator, modelled on Graphify's ideas (knowledge
// graph instead of grep, "god nodes", communities, explainable paths) but
// dependency-free TypeScript over the SHA-pinned snapshot files.
// Every node carries path + line at the pinned commit, so answers stay checkable.

export type NodeKind = "file" | "test" | "function" | "class" | "interface" | "type" | "const";
export type EdgeKind = "defines" | "imports" | "uses" | "tests";

export interface GNode { id: string; kind: NodeKind; label: string; path: string; line: number; community?: number; degree?: number }
export interface GEdge { from: string; to: string; kind: EdgeKind }
export interface CodeGraph {
  repository: string;
  sha: string;
  nodes: GNode[];
  edges: GEdge[];
  communities: { id: number; label: string; size: number }[];
  godNodes: string[];
}

const SRC = /\.(ts|tsx)$/;
const isTest = (p: string) => /(^|\/)tests?\//.test(p) || /\.test\./.test(p);
const DEF = /^\s*export\s+(?:default\s+)?(?:async\s+)?(function|class|interface|type|const)\s+([A-Za-z0-9_]+)/;

export function buildCodeGraph(repository: string, sha: string, files: { path: string; content: string }[]): CodeGraph {
  const src = files.filter((f) => SRC.test(f.path)).sort((a, b) => a.path.localeCompare(b.path));
  const paths = new Set(src.map((f) => f.path));
  const nodes = new Map<string, GNode>();
  const edges: GEdge[] = [];
  const exported = new Map<string, { name: string; id: string }[]>(); // path -> exported symbols

  for (const f of src) {
    const fid = `file:${f.path}`;
    nodes.set(fid, { id: fid, kind: isTest(f.path) ? "test" : "file", label: f.path.split("/").pop()!, path: f.path, line: 1 });
    const syms: { name: string; id: string }[] = [];
    f.content.split("\n").forEach((line, i) => {
      const m = line.match(DEF);
      if (!m) return;
      const sid = `sym:${f.path}#${m[2]}`;
      nodes.set(sid, { id: sid, kind: m[1] as NodeKind, label: m[2], path: f.path, line: i + 1 });
      edges.push({ from: fid, to: sid, kind: "defines" });
      syms.push({ name: m[2], id: sid });
    });
    exported.set(f.path, syms);
  }

  for (const f of src) {
    const fid = `file:${f.path}`;
    for (const m of f.content.matchAll(/from\s+["']([^"']+)["']/g)) {
      const target = resolveImport(f.path, m[1], paths);
      if (!target || target === f.path) continue;
      edges.push({ from: fid, to: `file:${target}`, kind: isTest(f.path) ? "tests" : "imports" });
      // symbol-level "uses": imported names that this file actually mentions
      const names = (m[0] && f.content.slice(0, m.index).split("import").pop()) || "";
      for (const s of exported.get(target) ?? []) {
        if (new RegExp(`\\b${s.name}\\b`).test(names)) edges.push({ from: fid, to: s.id, kind: isTest(f.path) ? "tests" : "uses" });
      }
    }
  }

  const deg = new Map<string, number>();
  for (const e of edges) { deg.set(e.from, (deg.get(e.from) ?? 0) + 1); deg.set(e.to, (deg.get(e.to) ?? 0) + 1); }
  for (const n of nodes.values()) n.degree = deg.get(n.id) ?? 0;

  const communities = detectCommunities([...nodes.values()], edges);
  const godNodes = [...nodes.values()].filter((n) => n.kind !== "test").sort((a, b) => (b.degree ?? 0) - (a.degree ?? 0) || a.id.localeCompare(b.id)).slice(0, 8).map((n) => n.id);
  return { repository, sha, nodes: [...nodes.values()], edges: dedupe(edges), communities, godNodes };
}

export function resolveImport(from: string, spec: string, paths: Set<string>): string | null {
  let base: string;
  if (spec.startsWith("@/")) base = spec.slice(2);
  else if (spec.startsWith(".")) {
    const parts = from.split("/").slice(0, -1);
    for (const seg of spec.split("/")) {
      if (seg === "..") parts.pop();
      else if (seg !== ".") parts.push(seg);
    }
    base = parts.join("/");
  } else return null; // external package
  for (const c of [base, `${base}.ts`, `${base}.tsx`, `${base}/index.ts`, `${base}/index.tsx`]) if (paths.has(c)) return c;
  return null;
}

/** Deterministic label propagation over the undirected graph (Graphify uses Leiden; LPA is a dependency-free stand-in). */
function detectCommunities(nodes: GNode[], edges: GEdge[]) {
  const adj = new Map<string, string[]>(nodes.map((n) => [n.id, []]));
  for (const e of edges) { adj.get(e.from)?.push(e.to); adj.get(e.to)?.push(e.from); }
  // seed labels by top-level folder so communities read like the codebase
  const label = new Map<string, string>(nodes.map((n) => [n.id, n.path.split("/").slice(0, 2).join("/")]));
  const order = nodes.map((n) => n.id).sort();
  for (let it = 0; it < 12; it++) {
    let changed = false;
    for (const id of order) {
      const counts = new Map<string, number>();
      for (const nb of adj.get(id) ?? []) counts.set(label.get(nb)!, (counts.get(label.get(nb)!) ?? 0) + 1);
      counts.set(label.get(id)!, (counts.get(label.get(id)!) ?? 0) + 0.5); // inertia
      const best = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0];
      if (best && best !== label.get(id)) { label.set(id, best); changed = true; }
    }
    if (!changed) break;
  }
  const ids = [...new Set(label.values())].sort();
  for (const n of nodes) n.community = ids.indexOf(label.get(n.id)!);
  return ids.map((l, i) => ({ id: i, label: l, size: nodes.filter((n) => n.community === i).length })).filter((c) => c.size > 0);
}

const dedupe = (es: GEdge[]) => [...new Map(es.map((e) => [`${e.from}>${e.to}>${e.kind}`, e])).values()];

// ---------------------------------------------------------------- query
export interface GraphAnswer {
  seed: GNode | null;
  path: { node: GNode; via: EdgeKind | "match"; why: string }[];
  subgraph: { nodes: string[]; edges: GEdge[] };
  match: "confirmed" | "candidate" | "none";
  explanation: string[];
}

const STOP = new Set("the a an is are where which what how does do in of to for and code file function kahan hai kya ka ki ke ko woh wo show me find".split(" "));

/** Find where a question lands in the code, and explain the hop-by-hop reasoning. */
export function queryGraph(g: CodeGraph, question: string, files: { path: string; content: string }[], changedInPr: Set<string> = new Set()): GraphAnswer {
  const words = question.toLowerCase().split(/[^a-z0-9_-]+/).filter((t) => t.length > 2 && !STOP.has(t));
  const stem = (w: string) => (w.length > 5 ? w.replace(/(ing|ies|es|ed|s)$/, "") : w);
  const terms = [...new Set(words.map(stem).filter((t) => t.length > 2))];
  // "read back" ~ read-back / read_back / readback (identifier styles)
  const phrases = words.slice(0, -1).flatMap((w, i) => [`${w}-${words[i + 1]}`, `${w}_${words[i + 1]}`, `${w}${words[i + 1]}`]);
  const content = new Map(files.map((f) => [f.path, f.content.toLowerCase()]));
  const byId = new Map(g.nodes.map((n) => [n.id, n]));
  // IDF: rare terms ("hysteresis", "dedupe") decide; common ones ("read", "code") barely count.
  const N = Math.max(1, content.size);
  const idf = new Map(terms.map((t) => [t, Math.log(1 + N / (1 + [...content.values()].filter((c) => c.includes(t)).length))]));
  const w = (ts: string[]) => ts.reduce((a, t) => a + (idf.get(t) ?? 1), 0);
  let best: { n: GNode; score: number; hits: string[] } | null = null;
  for (const n of g.nodes) {
    if (n.kind === "file" || n.kind === "test" || isTest(n.path)) continue; // tests are coverage, not the answer
    const name = n.label.toLowerCase();
    const text = content.get(n.path) ?? "";
    const body = docComment(text, n.line) + "\n" + sliceBody(text, n.line);
    const header = fileHeader(text);
    const nameHits = terms.filter((t) => name.includes(t.replace(/-/g, "")));
    const bodyHits = terms.filter((t) => !nameHits.includes(t) && body.includes(t));
    const phraseHits = phrases.filter((p) => body.includes(p) || name.includes(p));
    const headerHits = terms.filter((t) => !nameHits.includes(t) && !bodyHits.includes(t) && header.includes(t));
    const hits = [...nameHits, ...bodyHits, ...phraseHits, ...headerHits];
    const kindBias = n.kind === "function" ? 1.5 : n.kind === "class" ? 1 : n.kind === "const" ? 0.5 : -1;
    // Behaviour lives in lib/ and app/api; .tsx pages mostly hold copy about it.
    const layerBias = n.path.endsWith(".tsx") ? -2.5 : n.path.startsWith("scripts/") ? -1 : 0;
    const score = w(nameHits) * 2 + w(bodyHits) + phraseHits.length * 2 + w(headerHits) * 0.6 + kindBias + layerBias + Math.min(1, (n.degree ?? 0) / 20);
    if (hits.length && (!best || score > best.score)) best = { n, score, hits };
  }
  if (!best) return { seed: null, path: [], subgraph: { nodes: [], edges: [] }, match: "none", explanation: ["No symbol in the graph matches that question at this commit."] };

  const seed = best.n;
  const file = byId.get(`file:${seed.path}`)!;
  const users = g.edges.filter((e) => e.to === seed.id && e.kind === "uses").map((e) => byId.get(e.from)!).filter(Boolean);
  const tests = g.edges.filter((e) => (e.to === seed.id || e.to === file.id) && e.kind === "tests").map((e) => byId.get(e.from)!).filter(Boolean);
  const path: GraphAnswer["path"] = [
    { node: seed, via: "match", why: `“${best.hits.join("”, “")}” matched ${seed.kind} ${seed.label}` },
    { node: file, via: "defines", why: `defined in ${seed.path} at line ${seed.line}` },
    ...users.slice(0, 2).map((u) => ({ node: u, via: "uses" as const, why: `called from ${u.path}` })),
    ...tests.slice(0, 1).map((t) => ({ node: t, via: "tests" as const, why: `related test file ${t.path} (static link, execution unverified)` })),
  ];
  const ids = new Set(path.map((p) => p.node.id));
  // Static graph links help locate code; they cannot confirm task semantics,
  // coverage or completion merely because a file appears in a PR.
  const match = "candidate";
  return {
    seed,
    path,
    subgraph: { nodes: [...ids], edges: g.edges.filter((e) => ids.has(e.from) && ids.has(e.to)) },
    match,
    explanation: [
      ...path.map((p, i) => `${i + 1}. ${p.why}`),
      changedInPr.has(seed.path) ? "The file appears in the linked PR; this static graph result remains a candidate for review." : "Not linked to the PR, so treat it as a candidate until someone confirms.",
    ],
  };
}

/** Comment lines directly above a definition. */
function docComment(content: string, line: number): string {
  const lines = content.split("\n");
  const out: string[] = [];
  for (let i = line - 2; i >= 0 && /^\s*(\/\/|\/\*|\*)/.test(lines[i]); i--) out.unshift(lines[i]);
  return out.join("\n");
}

/** Leading comment lines in the first 25 lines of a file (its purpose statement). */
function fileHeader(content: string): string {
  return content.split("\n").slice(0, 25).filter((l) => /^\s*(\/\/|\/\*|\*)/.test(l)).join("\n");
}

/** The symbol's own body: from its definition to the next top-level export (max 80 lines). */
function sliceBody(content: string, line: number): string {
  const lines = content.split("\n");
  const out = [lines[line - 1] ?? ""];
  for (let i = line; i < Math.min(lines.length, line + 80); i++) {
    if (/^\s*export\s/.test(lines[i])) break;
    out.push(lines[i]);
  }
  return out.join("\n");
}

export function graphReport(g: CodeGraph): string {
  const byId = new Map(g.nodes.map((n) => [n.id, n]));
  return [
    `# Code graph — ${g.repository} @ ${g.sha.slice(0, 7)}`,
    "",
    `${g.nodes.length} nodes · ${g.edges.length} edges · ${g.communities.length} communities`,
    "",
    "## God nodes (most connected)",
    ...g.godNodes.map((id) => { const n = byId.get(id)!; return `- \`${n.label}\` (${n.kind}, ${n.path}:${n.line}) — degree ${n.degree}`; }),
    "",
    "## Communities",
    ...g.communities.sort((a, b) => b.size - a.size).map((c) => `- ${c.label} — ${c.size} nodes`),
    "",
  ].join("\n");
}

import type { EvidenceSnapshot } from "../contracts";
