import { contextVersion, ev, leaderPresence, tickets } from "./state";

// Unknown answer -> requester-approved ticket -> leader resolves (verified write)
// -> requester receives the answer with provenance. A ticket is never dropped and
// never answered by a model: only an authenticated, stepped-up leader resolves it.

type Fail = { ok: false; status: 400 | 403 | 404 | 409; reason: string };

const NEXT: Record<TicketState, TicketState[]> = {
  pending: ["answered", "withdrawn"],
  answered: ["delivered", "acknowledged"],
  delivered: ["acknowledged"],
  acknowledged: [],
  withdrawn: [],
};

export async function createTicket(
  store: EventStore,
  snapshot: EvidenceSnapshot,
  actor: Actor,
  body: Record<string, unknown>,
): Promise<{ ok: true; ticket: ClarificationTicket; replayed: boolean } | Fail> {
  const question = String(body.question ?? "").trim();
  const key = String(body.idempotency_key ?? body.idempotencyKey ?? "");
  if (body.confirmed !== true && body.confirmed !== "true") return { ok: false, status: 400, reason: "the requester must approve sending this question to the leader" };
  if (question.length < 5 || question.length > 300) return { ok: false, status: 400, reason: "question must be 5–300 characters" };
  if (key.length < 8) return { ok: false, status: 400, reason: "idempotency_key (8+ chars) required" };
  const meetingId = actor.meetingIds[0];
  if (!meetingId) return { ok: false, status: 403, reason: "no approved meeting for this person" };

  const normalizedQuestion = finalIntent(question).slice(0, 300);
  const result = await store.appendGuarded<{ ok: true; ticket: ClarificationTicket; replayed: boolean } | Fail>((log) => {
    const existing = [...tickets(log).values()].find((t) => (t as ClarificationTicket & { idempotencyKey?: string }).idempotencyKey === key && t.requesterId === actor.participant.id);
    if (existing) {
      if (!actor.meetingIds.includes(existing.meetingId))
        return { reject: { ok: false, status: 403, reason: "ticket is outside the authorized meeting scope" } };
      if (existing.question !== normalizedQuestion)
        return { reject: { ok: false, status: 409, reason: "idempotency key was already used for a different question" } };
      return { reject: { ok: true as const, ticket: existing, replayed: true } };
    }
    // A matching retry must succeed even if the leader answered meanwhile.
    // Check current memory only for a genuinely new ticket, under the write lock.
    const mem = askTeamMemory(snapshot, log, actor, question);
    if (mem.kind === "confirmed") return { reject: { ok: false, status: 409, reason: "that already has a confirmed answer" } };
    const decision = "decision" in mem ? mem.decision : undefined;
    const ticket: ClarificationTicket & { idempotencyKey: string } = {
      id: `clar_${randomBytes(5).toString("hex")}`,
      requesterId: actor.participant.id,
      question: mem.question.slice(0, 300),
      meetingId: decision?.meetingId ?? meetingId,
      contextRefs: (decision?.sources ?? []).map((s) => ({ ...s, label: s.label.slice(0, 120) })),
      decisionId: decision?.id,
      state: "pending",
      createdAt: new Date().toISOString(),
      leaderCall: { status: "not_requested", at: new Date().toISOString() },
      idempotencyKey: key,
    };
    return { append: ev("ticket", ticket.id, ticket), result: { ok: true as const, ticket, replayed: false } };
  });
  if (!result.ok) return result;
  const persisted = tickets(await store.all()).get(result.ticket.id);
  if (!persisted || persisted.requesterId !== actor.participant.id || persisted.question !== normalizedQuestion || !actor.meetingIds.includes(persisted.meetingId))
    return { ok: false, status: 409, reason: "ticket read-back failed; save was not confirmed" };
  return { ...result, ticket: persisted };
}

export async function leaderInbox(store: EventStore, snapshot: EvidenceSnapshot, actor: Actor) {
  const access = zoneAccess(actor, "leader_desk");
  if (!access.allowed) return { ok: false as const, status: 403 as const, reason: access.reason };
  const events = await store.all();
  const all = [...tickets(events).values()].filter((t) => actor.meetingIds.includes(t.meetingId));
  const decisions = currentDecisions(snapshot, events);
  return {
    ok: true as const,
    contextVersion: contextVersion(events),
    pending: all.filter((t) => t.state === "pending").map((t) => ({ ...t, requesterName: snapshot.participants.find((p) => p.id === t.requesterId)?.name, decision: decisions.find((d) => d.id === t.decisionId) ?? null })),
    recent: all.filter((t) => t.state !== "pending").slice(-10),
  };
}

export type ResolveResult =
  | { ok: true; decision: Decision; ticket: ClarificationTicket; contextVersion: number; readBack: true }
  | Fail;

export async function resolveTicket(store: EventStore, snapshot: EvidenceSnapshot, actor: Actor, body: Record<string, unknown>): Promise<ResolveResult> {
  const access = zoneAccess(actor, "leader_desk");
  if (!access.allowed) return { ok: false, status: 403, reason: access.reason };
  if (body.confirmed !== true && body.confirmed !== "true") return { ok: false, status: 400, reason: "leader must explicitly confirm the answer" };
  const ticketId = String(body.ticket_id ?? body.ticketId ?? "");
  const statement = String(body.statement ?? "").trim();
  const conditions = typeof body.conditions === "string" && body.conditions.trim() ? body.conditions.trim().slice(0, 300) : undefined;
  if (statement.length < 3 || statement.length > 400) return { ok: false, status: 400, reason: "statement must be 3–400 characters" };
  const expectedVersion = body.expected_version ?? body.expectedVersion;
  if (typeof expectedVersion !== "number" || !Number.isSafeInteger(expectedVersion) || expectedVersion < 0)
    return { ok: false, status: 400, reason: "expected_version must be the current nonnegative decision version" };

  const result = await store.appendGuarded<ResolveResult>((log) => {
    const t = tickets(log).get(ticketId);
    if (!t || !actor.meetingIds.includes(t.meetingId)) return { reject: { ok: false, status: 404, reason: "no such ticket" } };
    if (t.state !== "pending") return { reject: { ok: false, status: 409, reason: `ticket is already ${t.state}` } };
    const decisionId = t.decisionId ?? `dec:${t.id}`;
    const current = currentDecisions(snapshot, log).find((d) => d.id === decisionId);
    const currentVersion = current?.version ?? 0;
    if (expectedVersion !== currentVersion)
      return { reject: { ok: false, status: 409, reason: `decision changed (now v${currentVersion}); reload before approving` } };
    const at = new Date().toISOString();
    const decision: Decision = {
      id: decisionId,
      topic: current?.topic ?? t.question,
      statement,
      conditions,
      state: conditions ? "conditional" : "approved",
      ownerId: current?.ownerId,
      version: currentVersion + 1,
      meetingId: t.meetingId,
      approvedBy: actor.participant.id,
      approvedAt: at,
      sources: [...(current?.sources ?? t.contextRefs), { kind: "leader_resolution", id: t.id, label: `Leader resolution of "${t.question.slice(0, 80)}"` }],
    };
    const answered: ClarificationTicket = {
      ...t, state: "answered",
      answer: { decisionId, decisionVersion: decision.version, statement, conditions, approvedBy: actor.participant.id, approvedAt: at },
    };
    return {
      // One durable log record keeps the decision and ticket together even if
      // an append fails. Both projections read this same resolution event.
      append: ev("resolution", t.id, { decision, ticket: answered }, at),
      result: { ok: true, decision, ticket: answered, contextVersion: 0, readBack: true },
    };
  });
  if (!result.ok) return result;

  // Read-back from the persisted log before anyone is told it was saved.
  const after = await store.all();
  const persisted = currentDecisions(snapshot, after).find((d) => d.id === result.decision.id);
  const persistedTicket = tickets(after).get(result.ticket.id);
  if (!persisted || persisted.version !== result.decision.version || persisted.statement !== statement || persistedTicket?.state !== "answered")
    return { ok: false, status: 409, reason: "read-back failed; the answer was not confirmed as saved" };
  return { ...result, decision: persisted, ticket: persistedTicket, contextVersion: contextVersion(after) };
}

type TransitionResult = { ok: true; ticket: ClarificationTicket; replayed: boolean } | { ok: false; reason: string };
async function transition(store: EventStore, actor: Actor, ticketId: string, to: TicketState, ownerOnly = true): Promise<TransitionResult> {
  return store.appendGuarded<TransitionResult>((log) => {
    const t = tickets(log).get(ticketId);
    if (!t || !actor.meetingIds.includes(t.meetingId) || (ownerOnly && t.requesterId !== actor.participant.id)) return { reject: { ok: false as const, reason: "no such ticket" } };
    if (t.state === to) return { reject: { ok: true as const, ticket: t, replayed: true } };
    if (!NEXT[t.state].includes(to)) return { reject: { ok: false as const, reason: `cannot go from ${t.state} to ${to}` } };
    const next = { ...t, state: to };
    return { append: ev("ticket", t.id, next), result: { ok: true as const, ticket: next, replayed: false } };
  });
}

/** Answers waiting for the requester (works after reconnect: it's all in the log). */
export async function deliveries(store: EventStore, actor: Actor) {
  const ts = [...tickets(await store.all()).values()].filter((t) => t.requesterId === actor.participant.id && actor.meetingIds.includes(t.meetingId));
  return { answered: ts.filter((t) => t.state === "answered" || t.state === "delivered"), pending: ts.filter((t) => t.state === "pending") };
}
export const markDelivered = (store: EventStore, actor: Actor, id: string) => transition(store, actor, id, "delivered");
export const acknowledge = (store: EventStore, actor: Actor, id: string) => transition(store, actor, id, "acknowledged");
export const withdraw = (store: EventStore, actor: Actor, id: string) => transition(store, actor, id, "withdrawn");

/**
 * Ask for an optional Bolna clarification call to the leader. We never place it
 * unless the leader is marked available AND has consented to calls; otherwise
 * the ticket simply stays pending. Placing the call itself is an operator step.
 */
export async function requestLeaderCall(store: EventStore, snapshot: EvidenceSnapshot, actor: Actor, ticketId: string) {
  const leader = snapshot.participants.find((p) => p.role === "leader" && actor.meetingIds.some((m) => p.meetingIds.includes(m)));
  type CallResult = { ok: true; status: "unavailable" | "no_consent" | "requested"; ticket: ClarificationTicket } | { ok: false; reason: string };
  return store.appendGuarded<CallResult>((log) => {
    const t = tickets(log).get(ticketId);
    if (!t || t.requesterId !== actor.participant.id || !actor.meetingIds.includes(t.meetingId)) return { reject: { ok: false as const, reason: "no such ticket" } };
    if (t.state !== "pending") return { reject: { ok: false as const, reason: `ticket is ${t.state}` } };
    const presence = leader ? leaderPresence(log, leader.id) : { available: false, callConsent: false };
    const status: "unavailable" | "no_consent" | "requested" = !leader || !presence.available ? "unavailable" : !presence.callConsent ? "no_consent" : "requested";
    const next: ClarificationTicket = { ...t, leaderCall: { status, at: new Date().toISOString() } };
    return { append: ev("ticket", t.id, next), result: { ok: true as const, status, ticket: next } };
  });
}

export async function setPresence(store: EventStore, actor: Actor, body: Record<string, unknown>) {
  if (actor.role !== "leader") return { ok: false as const, reason: "only the leader sets leader availability" };
  const data = { available: body.available === true, callConsent: body.call_consent === true || body.callConsent === true };
  await store.append(ev("presence", actor.participant.id, data));
  return { ok: true as const, ...data };
}

import type { EventStore } from "../store/event-store";
import { ACTIVATION_METHODS, FOCUS_PROVIDERS, ZONES, type ActivationMethod, type FocusProvider, type Zone } from "./contracts";
import type { Actor } from "./identity";
import { ev, focusState } from "./state";

// Server side of FocusInput. Providers (AirPods companion, webcam, manual) send
// low-privilege selection events. Selection never grants anything; activation
// is a separate, explicit act that is authorized here.

export type FocusResult =
  | { ok: true; zone: Zone; seq: number; locked: boolean; lockReason?: string }
  | { ok: false; status: 400 | 409; reason: string };

export function zoneAccess(actor: Actor, zone: Zone): { allowed: true } | { allowed: false; reason: string } {
  if (zone === "leader_desk") {
    if (actor.role !== "leader") return { allowed: false, reason: "Leader Desk is for the verified team leader only" };
    if (!actor.stepUpFresh) return { allowed: false, reason: "leader must re-verify (step-up) before using the Leader Desk" };
  }
  if (zone === "code_navigator" && !actor.repoAccess) return { allowed: false, reason: "no access to the repository" };
  return { allowed: true };
}

export async function recordFocus(store: EventStore, actor: Actor, body: Record<string, unknown>): Promise<FocusResult> {
  const zone = body.zone as Zone;
  const provider = body.provider as FocusProvider;
  const seq = Number(body.seq);
  if (!ZONES.includes(zone)) return { ok: false, status: 400, reason: "unknown zone" };
  if (!FOCUS_PROVIDERS.includes(provider)) return { ok: false, status: 400, reason: "unknown focus provider" };
  if (!Number.isInteger(seq) || seq < 1) return { ok: false, status: 400, reason: "seq must be a positive integer" };
  if (Object.keys(body).some((k) => !["zone", "provider", "seq", "confidence", "session_token", "sessionToken"].includes(k)))
    return { ok: false, status: 400, reason: "unexpected fields in focus event" }; // e.g. a forged "role" or "activate"
  const access = zoneAccess(actor, zone);
  return store.appendGuarded<FocusResult>((events) => {
    const last = focusState(events, actor.sessionId);
    if (seq <= last.seq) return { reject: { ok: false, status: 409, reason: `stale or duplicate focus event (seq ${seq} <= ${last.seq})` } };
    return {
      append: ev("focus", actor.sessionId, { zone, provider, seq, confidence: Number(body.confidence ?? 1) }),
      result: { ok: true, zone, seq, locked: !access.allowed, lockReason: access.allowed ? undefined : access.reason },
    };
  });
}

export type ActivationResult = { ok: true; zone: Zone } | { ok: false; status: 400 | 403 | 409; reason: string };

export async function activateZone(store: EventStore, actor: Actor, body: Record<string, unknown>): Promise<ActivationResult> {
  const zone = body.zone as Zone;
  const method = body.method as ActivationMethod;
  if (!ZONES.includes(zone)) return { ok: false, status: 400, reason: "unknown zone" };
  if (!ACTIVATION_METHODS.includes(method)) return { ok: false, status: 400, reason: "activation must be explicit (tap, click, keyboard, voice command or double nod)" };
  const access = zoneAccess(actor, zone);
  if (!access.allowed) return { ok: false, status: 403, reason: access.reason };
  return store.appendGuarded<ActivationResult>((events) => {
    const f = focusState(events, actor.sessionId);
    // Activation applies to the zone the user has SELECTED; manual providers select and activate in one gesture.
    if (f.zone !== zone && method !== "click" && method !== "tap" && method !== "keyboard")
      return { reject: { ok: false, status: 409, reason: "activate the zone you have selected" } };
    return { append: ev("activation", actor.sessionId, { zone, method }), result: { ok: true, zone } };
  });
}

import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { hashToken } from "../auth/call-session";
import type { EvidenceSnapshot, Participant } from "../contracts";
import type { EventStore } from "../store/event-store";
import type { DeviceSession, Role } from "./contracts";
import { deviceSessionByHash, ev, latestStepUp, zoneEvents } from "./state";
import { credentials } from "./webauthn";

// Server-owned identity for the spatial zones. A client may present an opaque
// session token; role, repo access and leader step-up are derived here only.

export interface Actor {
  participant: Participant;
  role: Role;
  repoAccess: boolean;
  sessionId: string;
  channel: "device" | "call";
  stepUpFresh: boolean; // leader re-verified recently (privileged actions)
  meetingIds: string[];
}

export type ActorResult = { ok: true; actor: Actor } | { ok: false; status: 401 | 403; reason: string };

const STEP_UP_MINUTES = 10;

export async function issueDeviceSession(
  store: EventStore,
  snapshot: EvidenceSnapshot,
  input: { participantId: string; deviceLabel: string; ttlMinutes?: number },
): Promise<{ token: string; session: DeviceSession }> {
  if (!snapshot.participants.some((p) => p.id === input.participantId)) throw new Error("unknown participant");
  const token = randomBytes(24).toString("base64url");
  const session: DeviceSession = {
    sessionId: `dev_${randomBytes(6).toString("hex")}`,
    tokenHash: hashToken(token),
    participantId: input.participantId,
    deviceLabel: input.deviceLabel.slice(0, 60),
    expiresAt: new Date(Date.now() + (input.ttlMinutes ?? 240) * 60_000).toISOString(),
  };
  await store.append(ev("device_session", session.sessionId, session));
  return { token, session };
}

export async function resolveDeviceActor(store: EventStore, snapshot: EvidenceSnapshot, token: unknown, now = new Date()): Promise<ActorResult> {
  if (typeof token !== "string" || token.length < 16) return { ok: false, status: 401, reason: "missing session token" };
  const events = await store.all();
  const session = deviceSessionByHash(events, hashToken(token));
  if (!session) return { ok: false, status: 401, reason: "unknown session" };
  if (new Date(session.expiresAt) < now) return { ok: false, status: 401, reason: "session expired" };
  const participant = snapshot.participants.find((p) => p.id === session.participantId);
  if (!participant) return { ok: false, status: 403, reason: "participant not authorized" };
  const up = latestStepUp(events, session.sessionId);
  // Once the leader has enrolled a device passkey, only a passkey step-up counts.
  const passkeyOnly = credentials(events, participant.id).length > 0;
  return {
    ok: true,
    actor: {
      participant,
      role: participant.role ?? "member",
      repoAccess: participant.repoAccess ?? true,
      sessionId: session.sessionId,
      channel: "device",
      stepUpFresh: Boolean(up && new Date(up.expiresAt) > now && participant.role === "leader" && (!passkeyOnly || up.method === "passkey")),
      meetingIds: participant.meetingIds,
    },
  };
}

// ---- Leader step-up -------------------------------------------------------
// Pluggable verifier. The demo verifier is an HMAC one-time code derived from a
// server secret (KKB_LEADER_STEPUP_SECRET), delivered out of band to the leader
// (`npm run leader:code`). It is NOT a passkey; a WebAuthn verifier slots in here.

export interface StepUpVerifier {
  method: string;
  verify(sessionId: string, proof: unknown, now: Date): boolean;
}

export function leaderCode(secret: string, sessionId: string, now = new Date()): string {
  const window = Math.floor(now.getTime() / 300_000); // 5-minute windows
  const mac = createHmac("sha256", secret).update(`${sessionId}:${window}`).digest();
  return String(mac.readUInt32BE(0) % 1_000_000).padStart(6, "0");
}

export function hmacCodeVerifier(secret: string | undefined): StepUpVerifier {
  return {
    method: "server_otp",
    verify(sessionId, proof, now) {
      if (!secret || typeof proof !== "string" || !/^\d{6}$/.test(proof)) return false;
      const prev = new Date(now.getTime() - 300_000);
      return [leaderCode(secret, sessionId, now), leaderCode(secret, sessionId, prev)].some(
        (c) => timingSafeEqual(Buffer.from(c), Buffer.from(proof)),
      );
    },
  };
}

export async function stepUp(store: EventStore, actor: Actor, verifier: StepUpVerifier, proof: unknown, now = new Date()) {
  if (actor.role !== "leader") return { ok: false as const, reason: "only the verified leader can unlock the Leader Desk" };
  if (actor.channel !== "device") return { ok: false as const, reason: "step-up must happen on an authenticated device" };

  const expiresAt = new Date(now.getTime() + STEP_UP_MINUTES * 60_000).toISOString();
  type Result = { ok: true; expiresAt: string } | { ok: false; reason: string };
  return store.appendGuarded<Result>((events) => {
    if (credentials(events, actor.participant.id).length > 0)
      return { reject: { ok: false, reason: "a passkey is enrolled — unlock with that credential" } };
    const proofHash = verifier.method === "server_otp" && typeof proof === "string" ? hashToken(`${actor.sessionId}:${proof}`) : undefined;
    if (proofHash && zoneEvents(events, "step_up").some(e => e.key === actor.sessionId && e.data.proofHash === proofHash))
      return { reject: { ok: false, reason: "one-time proof has already been used" } };
    const attempts = zoneEvents(events, "step_up_attempt").filter(e => e.data.participantId === actor.participant.id && Date.parse(e.at) > now.getTime() - 600_000);
    if (attempts.length >= 5) return { reject: { ok: false, reason: "too many verification attempts; retry after ten minutes" } };
    if (!verifier.verify(actor.sessionId, proof, now))
      return { append: ev("step_up_attempt", actor.sessionId, { participantId: actor.participant.id }, now.toISOString()), result: { ok: false, reason: "verification failed" } };
    return { append: ev("step_up", actor.sessionId, { method: verifier.method, expiresAt, proofHash }, now.toISOString()), result: { ok: true, expiresAt } };
  });
}

import { randomBytes } from "node:crypto";
import type { EventStore } from "../store/event-store";
import type { Consent, LiveUtterance } from "./contracts";
import type { Actor } from "./identity";
import { ev, latestConsent, utterances } from "./state";

// Application live-STT lane (NOT Wispr MCP). Each device opts in separately.
// The browser/companion does speech-to-text; we receive text events only and
// never store raw audio. Everything here stays "provisional" until reconciled,
// and it can never overwrite an approved decision.

export async function setConsent(store: EventStore, actor: Actor, body: Record<string, unknown>): Promise<{ ok: true; consent: Consent } | { ok: false; reason: string }> {
  if (actor.channel !== "device") return { ok: false, reason: "consent is given per device session" };
  const consent: Consent = {
    microphone: body.microphone === true,
    shareWithTeam: body.microphone === true && body.share_with_team === true,
    recordedAt: new Date().toISOString(),
    receiptId: `consent_${randomBytes(5).toString("hex")}`,
  };
  await store.append(ev("consent", actor.sessionId, consent));
  return { ok: true, consent };
}

export type IngestResult =
  | { ok: true; status: "accepted" | "duplicate"; eventId: string }
  | { ok: false; status: 400 | 403 | 409; reason: string };

export async function ingestUtterance(store: EventStore, actor: Actor, body: Record<string, unknown>): Promise<IngestResult> {
  const eventId = String(body.event_id ?? "");
  const utteranceId = String(body.utterance_id ?? "");
  const seq = Number(body.seq);
  const text = typeof body.text === "string" ? body.text.trim() : "";
  const meetingId = typeof body.meeting_id === "string" ? body.meeting_id : actor.meetingIds.length === 1 ? actor.meetingIds[0] : undefined;
  if (!meetingId || !actor.meetingIds.includes(meetingId)) return { ok: false, status: 403, reason: "select an authorized meeting for this utterance" };
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(eventId) || !/^[A-Za-z0-9_-]{4,64}$/.test(utteranceId)) return { ok: false, status: 400, reason: "event_id and utterance_id required" };
  if (!Number.isInteger(seq) || seq < 1) return { ok: false, status: 400, reason: "seq must be a positive integer" };
  if (!text || text.length > 2000) return { ok: false, status: 400, reason: "text must be 1–2000 characters" };
  if ("audio" in body || "participant_id" in body) return { ok: false, status: 400, reason: "audio and client-supplied identity are not accepted" };

  return store.appendGuarded<IngestResult>((log) => {
    const consent = latestConsent(log, actor.sessionId);
    if (!consent?.microphone) return { reject: { ok: false, status: 403, reason: "microphone consent is off for this device" } };
    const mine = utterances(log).filter((u) => u.sessionId === actor.sessionId);
    if (mine.some((u) => u.eventId === eventId)) return { reject: { ok: true, status: "duplicate", eventId } }; // reconnect replay
    if (mine.some((u) => u.seq === seq)) return { reject: { ok: false, status: 409, reason: `seq ${seq} already used by another event` } };
    if (body.is_final !== true && mine.some((u) => u.utteranceId === utteranceId && u.isFinal))
      return { reject: { ok: false, status: 409, reason: "late provisional revision after final; ignored" } };
    const u: LiveUtterance = {
      eventId, utteranceId, seq, text,
      sessionId: actor.sessionId,
      participantId: actor.participant.id, // from the server session, never the client
      meetingId,
      isFinal: body.is_final === true,
      speakerConfidence: clamp(Number(body.speaker_confidence ?? 1)),
      language: typeof body.language === "string" ? body.language.slice(0, 12) : undefined,
      capturedAt: typeof body.captured_at === "string" ? body.captured_at : new Date().toISOString(),
      receivedAt: new Date().toISOString(),
      source: "app_live_stt",
      status: "provisional",
      visibility: consent.shareWithTeam ? "team" : "private",
    };
    return { append: ev("utterance", eventId, u), result: { ok: true, status: "accepted", eventId } };
  });
}

const clamp = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0);

import type { EvidenceSnapshot } from "../contracts";
import type { StoredEvent } from "../store/event-store";
import type { ClarificationTicket, Decision, LiveUtterance, SourceRef } from "./contracts";
import type { Actor } from "./identity";
import { latestConsent, loggedDecisions, tickets, utterances } from "./state";

// LEFT — Team Memory. Answers only from APPROVED, authorized context. Anything
// else is said to be unconfirmed and offered as a leader clarification.
// Retrieved text is quoted as data; it is never executed or obeyed.

/** Base decisions derived from the approved meeting snapshot (Wispr lane). */
export function baseDecisions(snapshot: EvidenceSnapshot): Decision[] {
  return snapshot.tasks.map((t) => {
    const approvedMeeting = snapshot.meetings.some(m => m.id === t.meetingId && m.approvedBy.trim());
    const passages = snapshot.passages.filter(p => t.passageIds.includes(p.id) && p.meetingId === t.meetingId);
    return {
    id: `dec:${t.id}`,
    topic: t.title,
    statement: t.title,
    state: t.assignment.state === "accepted" && approvedMeeting && passages.length > 0 ? "approved" : t.assignment.state === "disputed" ? "disputed" : "proposed",
    ownerId: t.assignment.ownerId,
    version: 1,
    meetingId: t.meetingId,
    sources: passages.map((p) => {
      return { kind: "wispr_meeting" as const, id: p.id, meetingId: t.meetingId, label: `${p.speaker ?? "speaker"}: "${p.text.slice(0, 160)}"` };
    }),
  } as Decision;
  });
}

/** Current decision memory: snapshot base overlaid by verified leader resolutions. */
export function currentDecisions(snapshot: EvidenceSnapshot, events: StoredEvent[]): Decision[] {
  const logged = loggedDecisions(events);
  const merged = new Map<string, Decision>(baseDecisions(snapshot).map((d) => [d.id, d]));
  for (const [id, d] of logged) if (!merged.has(id) || d.version > merged.get(id)!.version) merged.set(id, d);
  return [...merged.values()];
}

export const visibleDecisions = (snapshot: EvidenceSnapshot, events: StoredEvent[], actor: Actor) =>
  currentDecisions(snapshot, events).filter((d) => actor.meetingIds.includes(d.meetingId)).flatMap(d => {
    const sources = d.sources.filter(ref => {
      if (ref.kind !== "wispr_meeting") return true;
      const passage = snapshot.passages.find(p => p.id === ref.id && p.meetingId === d.meetingId);
      return passage && (passage.visibility === "team" || snapshot.tasks.some(t => actor.participant.taskIds.includes(t.id) && t.passageIds.includes(passage.id)));
    });
    return d.sources.length > 0 && sources.length === 0 ? [] : [{ ...d, sources }];
  });

const STOP = new Set("the a an is are was it to of and or for in on at by be do does did what when who whom which where how why we our us you your i me my this that with from have has will would should can could kya kab kaun kis hai tha ka ki ke ko se mein aur ya bhi agar wait sorry matlab actually umm uh hmm".split(" "));
export const terms = (s: string) =>
  [...new Set(s.toLowerCase().replace(/[^a-z0-9\s-]/g, " ").split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w)))];

/**
 * Hinglish self-corrections: keep what follows the LAST correction marker.
 * "deadline kab hai — nahi, matlab owner kaun hai" -> "owner kaun hai".
 */
export function finalIntent(q: string): string {
  const parts = q.split(/\b(?:no wait|i mean|sorry,?|actually|nahi,? matlab|matlab|nahi nahi|scratch that)\b/i);
  const last = parts[parts.length - 1].replace(/^[\s,.\-—–]+/, "").trim();
  return last.length >= 6 ? last : q.trim();
}

export type MemoryAnswer =
  | { kind: "confirmed" | "conditional"; decision: Decision; speak: string; sources: SourceRef[]; offerEscalation: false }
  | { kind: "not_confirmed"; decision: Decision; speak: string; sources: SourceRef[]; offerEscalation: true; pendingTicket?: ClarificationTicket }
  | { kind: "unknown"; speak: string; sources: []; offerEscalation: true; pendingTicket?: ClarificationTicket };

export function askTeamMemory(snapshot: EvidenceSnapshot, events: StoredEvent[], actor: Actor, rawQuestion: string): MemoryAnswer & { provisional: LiveUtterance[]; question: string } {
  const question = finalIntent(rawQuestion);
  const q = terms(question);
  const decisions = visibleDecisions(snapshot, events, actor);
  const scored = decisions
    .map((d) => {
      const hay = terms(`${d.topic} ${d.statement} ${d.conditions ?? ""} ${d.sources.map((s) => s.label).join(" ")}`);
      return { d, score: q.filter((t) => hay.some((h) => h === t || (t.length > 4 && h.startsWith(t.slice(0, 5))))).length };
    })
    .filter((x) => x.score >= Math.min(2, Math.max(1, q.length)))
    .sort((a, b) => b.score - a.score || stateRank(b.d) - stateRank(a.d));

  const myOpen = [...tickets(events).values()].find(
    (t) => t.requesterId === actor.participant.id && actor.meetingIds.includes(t.meetingId) && t.state === "pending" && q.length > 0 && terms(t.question).filter((x) => q.includes(x)).length >= Math.min(2, q.length),
  );
  const provisional = visibleUtterances(events, actor).filter((u) => terms(u.text).filter((x) => q.includes(x)).length >= 2).slice(-2);
  const live = provisional.length ? ` There's also an unreviewed live remark on this, which is provisional and not a decision.` : "";

  const best = scored[0]?.d;
  if (!best) {
    return {
      kind: "unknown", question, provisional, sources: [], offerEscalation: true, pendingTicket: myOpen,
      speak: myOpen
        ? `I still don't have a confirmed answer. Your question to the leader is pending.${live}`
        : `I don't have a confirmed answer to that in the approved meeting notes. Want me to ask the leader?${live}`,
    };
  }
  const who = best.approvedBy ? ` — approved by ${nameOf(snapshot, best.approvedBy)}` : "";
  if (best.state === "approved")
    return { kind: "confirmed", decision: best, question, provisional, sources: best.sources, offerEscalation: false, speak: `Confirmed${who}: ${best.statement}.${live}` };
  if (best.state === "conditional")
    return { kind: "conditional", decision: best, question, provisional, sources: best.sources, offerEscalation: false, speak: `Only conditionally approved${who}: ${best.statement}, on condition that ${best.conditions}. It is not unconditional.${live}` };
  return {
    kind: "not_confirmed", decision: best, question, provisional, sources: best.sources, offerEscalation: true, pendingTicket: myOpen,
    speak: `${best.state === "disputed" ? "That's disputed" : "That was only proposed, not confirmed"}: ${best.statement}. ${myOpen ? "Your question to the leader is still pending." : "Want me to ask the leader to confirm?"}${live}`,
  };
}

const stateRank = (d: Decision) => ({ approved: 4, conditional: 3, proposed: 2, disputed: 1, superseded: 0 })[d.state];
export const nameOf = (s: EvidenceSnapshot, id: string) => s.participants.find((p) => p.id === id)?.name ?? "the leader";

// ---- live utterances visible to an actor ------------------------------------
export function visibleUtterances(events: StoredEvent[], actor: Actor): LiveUtterance[] {
  const all = utterances(events).filter((u) => {
    if (!u.meetingId || !actor.meetingIds.includes(u.meetingId)) return false;
    if (u.participantId === actor.participant.id) return true;
    const consent = latestConsent(events, u.sessionId);
    return u.visibility === "team" && consent?.microphone === true && consent.shareWithTeam === true;
  });
  // Final supersedes provisional for the same utteranceId; order by session seq (not device clock).
  const byUtt = new Map<string, LiveUtterance>();
  for (const u of all) {
    const key = JSON.stringify([u.sessionId, u.utteranceId]);
    const prev = byUtt.get(key);
    if (!prev || (u.isFinal && !prev.isFinal) || (u.isFinal === prev.isFinal && u.seq > prev.seq)) byUtt.set(key, u);
  }
  return [...byUtt.values()].sort((a, b) => a.sessionId.localeCompare(b.sessionId) || a.seq - b.seq);
}

import type { EvidenceSnapshot } from "../contracts";
import type { EventStore } from "../store/event-store";
import { navigateCode } from "./code";
import { acknowledge, createTicket, deliveries, leaderInbox, markDelivered, requestLeaderCall, resolveTicket, setPresence, withdraw } from "./escalation";
import { activateZone, recordFocus, zoneAccess } from "./focus";
import { hmacCodeVerifier, resolveDeviceActor, stepUp, type StepUpVerifier } from "./identity";
import { ingestUtterance, setConsent } from "./live";
import { askTeamMemory, nameOf } from "./memory";
import { contextVersion, focusState, latestConsent } from "./state";
import { assertPasskey, issueChallenge, registerPasskey } from "./webauthn";
import { getCodeGraph } from "../codegraph/load";
import { queryGraph } from "../codegraph/graph";

// Framework-free dispatcher for the browser / native companion API
// (app/api/zones/[action]/route.ts). Deny by default: every action resolves the
// actor from a server-issued device session token first.

export interface ZoneRuntime {
  store: EventStore;
  snapshot: EvidenceSnapshot;
  stepUpVerifier?: StepUpVerifier;
}

export const ZONE_ACTIONS = [
  "me", "focus", "activate", "consent", "utterance", "memory_ask", "ticket_create", "ticket_withdraw", "ticket_call_leader",
  "deliveries", "delivery_seen", "delivery_ack", "code_navigate", "leader_step_up", "leader_presence", "leader_inbox", "leader_resolve",
  "passkey_options", "passkey_register", "passkey_assert", "code_graph_query",
] as const;
export type ZoneAction = (typeof ZONE_ACTIONS)[number];

export async function runZoneAction(rt: ZoneRuntime, action: ZoneAction, token: unknown, body: Record<string, unknown>): Promise<{ status: number; body: Record<string, unknown> }> {
  const auth = await resolveDeviceActor(rt.store, rt.snapshot, token);
  if (!auth.ok) return { status: auth.status, body: { ok: false, error: auth.reason } };
  const actor = auth.actor;
  const r = (status: number, b: object) => ({ status, body: b as Record<string, unknown> });
  const fail = (x: { ok: false; status?: number; reason: string }) => r(x.status ?? 400, { ok: false, error: x.reason });

  switch (action) {
    case "me": {
      const events = await rt.store.all();
      return r(200, {
        ok: true,
        participant: { id: actor.participant.id, name: actor.participant.name },
        role: actor.role,
        stepUpFresh: actor.stepUpFresh,
        zones: Object.fromEntries((["team_memory", "leader_desk", "code_navigator"] as const).map((z) => [z, zoneAccess(actor, z)])),
        focus: focusState(events, actor.sessionId),
        consent: latestConsent(events, actor.sessionId),
        contextVersion: contextVersion(events),
        snapshot: { label: rt.snapshot.label, repository: rt.snapshot.repository, pinnedSha: rt.snapshot.pinnedSha },
      });
    }
    case "focus": { const x = await recordFocus(rt.store, actor, body); return x.ok ? r(200, x) : fail(x); }
    case "activate": { const x = await activateZone(rt.store, actor, body); return x.ok ? r(200, x) : fail(x); }
    case "consent": { const x = await setConsent(rt.store, actor, body); return x.ok ? r(200, x) : fail(x); }
    case "utterance": { const x = await ingestUtterance(rt.store, actor, body); return x.ok ? r(200, x) : fail(x); }
    case "memory_ask": {
      const events = await rt.store.all();
      const a = askTeamMemory(rt.snapshot, events, actor, String(body.question ?? ""));
      return r(200, {
        ok: true, kind: a.kind, speak: a.speak, question: a.question, offerEscalation: a.offerEscalation,
        decision: "decision" in a ? { ...a.decision, approvedByName: a.decision.approvedBy ? nameOf(rt.snapshot, a.decision.approvedBy) : undefined } : null,
        sources: a.sources, pendingTicket: "pendingTicket" in a ? a.pendingTicket ?? null : null,
        provisional: a.provisional.map((u) => ({ text: u.text, status: u.status, source: u.source, speakerConfidence: u.speakerConfidence })),
        contextVersion: contextVersion(events), label: rt.snapshot.label,
      });
    }
    case "ticket_create": { const x = await createTicket(rt.store, rt.snapshot, actor, body); return x.ok ? r(200, x) : fail(x); }
    case "ticket_withdraw": { const x = await withdraw(rt.store, actor, String(body.ticket_id ?? "")); return x.ok ? r(200, x) : r(409, { ok: false, error: x.reason }); }
    case "ticket_call_leader": { const x = await requestLeaderCall(rt.store, rt.snapshot, actor, String(body.ticket_id ?? "")); return x.ok ? r(200, x) : r(409, { ok: false, error: x.reason }); }
    case "deliveries": return r(200, { ok: true, ...(await deliveries(rt.store, actor)), contextVersion: contextVersion(await rt.store.all()) });
    case "delivery_seen": { const x = await markDelivered(rt.store, actor, String(body.ticket_id ?? "")); return x.ok ? r(200, x) : r(409, { ok: false, error: x.reason }); }
    case "delivery_ack": { const x = await acknowledge(rt.store, actor, String(body.ticket_id ?? "")); return x.ok ? r(200, x) : r(409, { ok: false, error: x.reason }); }
    case "code_navigate": { const x = navigateCode(rt.snapshot, actor, String(body.question ?? ""), typeof body.task_id === "string" ? body.task_id : undefined); return x.ok ? r(200, x) : fail(x); }
    case "leader_step_up": {
      const x = await stepUp(rt.store, actor, rt.stepUpVerifier ?? hmacCodeVerifier(process.env.KKB_LEADER_STEPUP_SECRET), body.code);
      return x.ok ? r(200, x) : r(403, { ok: false, error: x.reason });
    }
    case "leader_presence": { const x = await setPresence(rt.store, actor, body); return x.ok ? r(200, x) : r(403, { ok: false, error: x.reason }); }
    case "leader_inbox": { const x = await leaderInbox(rt.store, rt.snapshot, actor); return x.ok ? r(200, x) : fail(x); }
    case "passkey_options": {
      if (actor.role !== "leader") return r(403, { ok: false, error: "only the leader uses a passkey here" });
      return r(200, { ok: true, ...(await issueChallenge(rt.store, actor, body.purpose === "register" ? "register" : "assert")) });
    }
    case "passkey_register": { const x = await registerPasskey(rt.store, actor, body); return x.ok ? r(200, x) : r(403, { ok: false, error: x.reason }); }
    case "passkey_assert": { const x = await assertPasskey(rt.store, actor, body); return x.ok ? r(200, x) : r(403, { ok: false, error: x.reason }); }
    case "code_graph_query": {
      const access = zoneAccess(actor, "code_navigator");
      if (!access.allowed) return r(403, { ok: false, error: access.reason });
      const g = getCodeGraph(rt.snapshot);
      const task = typeof body.task_id === "string" ? rt.snapshot.tasks.find(t => t.id === body.task_id && actor.participant.taskIds.includes(t.id) && actor.meetingIds.includes(t.meetingId)) : undefined;
      if (body.task_id && !task) return r(403, { ok: false, error: "task not authorized" });
      const pr = task?.prNumber != null ? rt.snapshot.pullRequests.find(p => p.number === task.prNumber && p.repository === rt.snapshot.repository) : undefined;
      const a = queryGraph(g, String(body.question ?? ""), rt.snapshot.files, new Set(pr?.changedFiles ?? []));
      // Return only this authorized snapshot, with a bounded visual subset.
      // Prefer the answer path so truncation cannot hide its code pointers.
      const selected = new Set(a.subgraph.nodes);
      const nodes = [...g.nodes.filter(n => selected.has(n.id)), ...g.nodes.filter(n => !selected.has(n.id))].slice(0, 600);
      const ids = new Set(nodes.map(n => n.id));
      const graph = { nodes, edges: g.edges.filter(e => ids.has(e.from) && ids.has(e.to)).slice(0, 1800), godNodes: g.godNodes.filter(id => ids.has(id)), sha: g.sha, repository: g.repository };
      return r(200, { ok: true, ...a, graph, sha: g.sha, repository: g.repository, label: rt.snapshot.label, engine: "builtin_static_graph" });
    }
    case "leader_resolve": { const x = await resolveTicket(rt.store, rt.snapshot, actor, body); return x.ok ? r(200, x) : fail(x); }
  }
}

import type { StoredEvent, ZoneEvent } from "../store/event-store";
import type { ClarificationTicket, Consent, Decision, DeviceSession, LiveUtterance, Zone } from "./contracts";

// Typed views over the append-only log. Every projection is a pure fold, so the
// same events always produce the same state (and tests can replay them).

export type ZoneKind =
  | "device_session"
  | "step_up"
  | "step_up_attempt"
  | "consent"
  | "focus"
  | "activation"
  | "decision"
  | "resolution"
  | "ticket"
  | "utterance"
  | "presence"
  | "bolna_execution"
  | "passkey"
  | "passkey_verified"
  | "webauthn_challenge"
  | "webauthn_used";

export const zoneEvents = (events: StoredEvent[], kind?: ZoneKind): ZoneEvent[] =>
  events.filter((e): e is ZoneEvent => e.type === "zone" && (!kind || e.kind === kind));

export const ev = (kind: ZoneKind, key: string, data: object, at = new Date().toISOString()): ZoneEvent => ({
  type: "zone",
  at,
  kind,
  key,
  data: data as Record<string, unknown>,
});

export function deviceSessionByHash(events: StoredEvent[], tokenHash: string): DeviceSession | null {
  const hit = zoneEvents(events, "device_session").find((e) => (e.data as unknown as DeviceSession).tokenHash === tokenHash);
  return hit ? (hit.data as unknown as DeviceSession) : null;
}

export function latestStepUp(events: StoredEvent[], sessionId: string): { method: string; expiresAt: string } | null {
  const ups = zoneEvents(events).filter((e) => (e.kind === "step_up" || e.kind === "passkey_verified") && e.key === sessionId);
  const latest = ups[ups.length - 1];
  return latest ? ((latest.kind === "passkey_verified" ? latest.data.stepUp : latest.data) as { method: string; expiresAt: string }) : null;
}

export function latestConsent(events: StoredEvent[], sessionId: string): Consent | null {
  const cs = zoneEvents(events, "consent").filter((e) => e.key === sessionId);
  return cs.length ? (cs[cs.length - 1].data as unknown as Consent) : null;
}

export function focusState(events: StoredEvent[], sessionId: string): { zone: Zone | null; seq: number; activeZone: Zone | null } {
  const f = zoneEvents(events, "focus").filter((e) => e.key === sessionId);
  const a = zoneEvents(events, "activation").filter((e) => e.key === sessionId);
  const last = f[f.length - 1]?.data as { zone: Zone; seq: number } | undefined;
  return { zone: last?.zone ?? null, seq: last?.seq ?? 0, activeZone: (a[a.length - 1]?.data as { zone: Zone } | undefined)?.zone ?? null };
}

/** Latest version of each decision recorded in the log (leader resolutions). */
export function loggedDecisions(events: StoredEvent[]): Map<string, Decision> {
  const m = new Map<string, Decision>();
  for (const e of zoneEvents(events).filter(e => e.kind === "decision" || e.kind === "resolution")) {
    const d = (e.kind === "resolution" ? e.data.decision : e.data) as Decision;
    const prev = m.get(d.id);
    if (!prev || d.version > prev.version) m.set(d.id, d);
  }
  return m;
}

/** Tickets fold: latest record per ticket id wins (state machine enforced on write). */
export function tickets(events: StoredEvent[]): Map<string, ClarificationTicket> {
  const m = new Map<string, ClarificationTicket>();
  for (const e of zoneEvents(events).filter(e => e.kind === "ticket" || e.kind === "resolution"))
    m.set(e.key, (e.kind === "resolution" ? e.data.ticket : e.data) as ClarificationTicket);
  return m;
}

export function utterances(events: StoredEvent[]): LiveUtterance[] {
  return zoneEvents(events, "utterance").map((e) => e.data as unknown as LiveUtterance);
}

/** Global context version: bumps whenever approved team memory changes. */
export function contextVersion(events: StoredEvent[]): number {
  return 1 + zoneEvents(events).filter(e => e.kind === "decision" || e.kind === "resolution").length;
}

export function leaderPresence(events: StoredEvent[], participantId: string): { available: boolean; callConsent: boolean } {
  const p = zoneEvents(events, "presence").filter((e) => e.key === participantId);
  return (p[p.length - 1]?.data as { available: boolean; callConsent: boolean } | undefined) ?? { available: false, callConsent: false };
}

/**
 * The zone this participant most recently ACTIVATED on any of their devices
 * (head turn / webcam / keyboard selection + explicit activation), if fresh.
 * Lets the phone agent follow what the caller is looking at on screen.
 */
export function latestActivatedZone(events: StoredEvent[], participantId: string, now = Date.now(), maxAgeMs = 10 * 60_000): Zone | null {
  const mine = new Set(zoneEvents(events, "device_session").filter((e) => (e.data as unknown as DeviceSession).participantId === participantId).map((e) => e.key));
  const acts = zoneEvents(events, "activation").filter((e) => mine.has(e.key) && now - Date.parse(e.at) <= maxAgeMs);
  return (acts[acts.length - 1]?.data as { zone: Zone } | undefined)?.zone ?? null;
}

import { createHash, createPublicKey, randomBytes, verify as cryptoVerify, type JsonWebKey } from "node:crypto";
import type { EventStore } from "../store/event-store";
import type { Actor } from "./identity";
import { ev, latestStepUp, zoneEvents } from "./state";

// Credential-bound leader step-up with a WebAuthn passkey. Only public keys are
// stored. Synced passkeys are possible; this does not attest physical hardware.
//
// Once a leader has enrolled a passkey, the Leader Desk accepts ONLY a passkey
// assertion from an enrolled credential (the demo one-time code stops working).

export interface PasskeyConfig { rpId: string; origin: string }
export const passkeyConfig = (): PasskeyConfig => {
  const origin = process.env.KKB_ORIGIN?.trim() || process.env.KKB_PUBLIC_URL?.trim() || "http://localhost:3000";
  const url = new URL(origin);
  if (url.origin !== origin || (url.protocol !== "https:" && !(url.protocol === "http:" && ["localhost", "127.0.0.1"].includes(url.hostname))))
    throw new Error("WebAuthn requires a configured HTTPS origin (localhost allowed for development)");
  const rpId = process.env.KKB_RP_ID?.trim() || url.hostname;
  if (url.hostname !== rpId && !url.hostname.endsWith(`.${rpId}`)) throw new Error("WebAuthn RP ID must match the configured host");
  return { rpId, origin };
};

export interface StoredCredential { participantId: string; credentialId: string; jwk: JsonWebKey; signCount: number; createdAt: string }

const b64u = (b: Buffer) => b.toString("base64url");
const fromB64u = (s: unknown) => Buffer.from(String(s ?? ""), "base64url");
const sha256 = (b: Buffer | string) => createHash("sha256").update(b).digest();

export function credentials(events: Parameters<typeof zoneEvents>[0], participantId?: string): StoredCredential[] {
  // latest record per credential id (sign counter updates are appended)
  const m = new Map<string, StoredCredential>();
  for (const e of zoneEvents(events).filter(e => e.kind === "passkey" || e.kind === "passkey_verified")) {
    const c = (e.kind === "passkey_verified" ? e.data.credential : e.data) as StoredCredential;
    if (!participantId || c.participantId === participantId) m.set(c.credentialId, c);
  }
  return [...m.values()];
}

/** Issue a single-use challenge bound to this device session. */
export async function issueChallenge(store: EventStore, actor: Actor, purpose: "register" | "assert") {
  const challenge = b64u(randomBytes(32));
  await store.append(ev("webauthn_challenge", actor.sessionId, { challenge, purpose, expiresAt: new Date(Date.now() + 120_000).toISOString() }));
  const cfg = passkeyConfig();
  const creds = credentials(await store.all(), actor.participant.id);
  return {
    challenge,
    rpId: cfg.rpId,
    user: { id: b64u(Buffer.from(actor.participant.id)), name: actor.participant.name },
    allowCredentials: creds.map((c) => c.credentialId),
  };
}

async function consumeChallenge(store: EventStore, sessionId: string, purpose: string, presented: string): Promise<boolean> {
  return store.appendGuarded<boolean>((log) => {
    const cs = zoneEvents(log, "webauthn_challenge").filter((e) => e.key === sessionId);
    const used = new Set(zoneEvents(log, "webauthn_used").map((e) => e.key));
    const hit = cs.reverse().find((e) => (e.data as { challenge: string }).challenge === presented);
    const d = hit?.data as { challenge: string; purpose: string; expiresAt: string } | undefined;
    if (!d || d.purpose !== purpose || used.has(d.challenge) || new Date(d.expiresAt) < new Date()) return { reject: false };
    return { append: ev("webauthn_used", d.challenge, { at: new Date().toISOString() }), result: true };
  });
}

function checkClientData(raw: Buffer, type: string, cfg: PasskeyConfig): { ok: true; challenge: string } | { ok: false; reason: string } {
  let cd: { type?: string; challenge?: string; origin?: string; crossOrigin?: boolean };
  try { cd = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, reason: "bad clientDataJSON" }; }
  if (!cd || typeof cd !== "object" || cd.type !== type) return { ok: false, reason: "wrong ceremony type" };
  if (cd.origin !== cfg.origin) return { ok: false, reason: "origin mismatch" };
  if (cd.crossOrigin !== undefined && cd.crossOrigin !== false) return { ok: false, reason: "cross-origin ceremony refused" };
  if (typeof cd.challenge !== "string" || !/^[A-Za-z0-9_-]{32,128}$/.test(cd.challenge)) return { ok: false, reason: "missing challenge" };
  return { ok: true, challenge: cd.challenge };
}

interface AuthData { rpIdHash: Buffer; flags: number; signCount: number; credentialId?: Buffer; cose?: Map<number, unknown> }
export function parseAuthData(b: Buffer): AuthData {
  if (!Buffer.isBuffer(b) || b.length < 37) throw new Error("truncated authenticator data");
  const out: AuthData = { rpIdHash: b.subarray(0, 32), flags: b[32], signCount: b.readUInt32BE(33) };
  if (out.flags & 0x40) {
    if (b.length < 56) throw new Error("truncated attested credential");
    const len = b.readUInt16BE(53);
    if (len < 1 || len > 1024 || b.length <= 55 + len) throw new Error("invalid credential length");
    out.credentialId = b.subarray(55, 55 + len);
    const cose = decodeCbor(b.subarray(55 + len)).value;
    if (!(cose instanceof Map)) throw new Error("invalid credential key");
    out.cose = cose;
  }
  return out;
}

function checkAuthData(ad: AuthData, cfg: PasskeyConfig): string | null {
  if (!ad.rpIdHash.equals(sha256(cfg.rpId))) return "rpId mismatch";
  if (!(ad.flags & 0x01)) return "user not present";
  if (!(ad.flags & 0x04)) return "user not verified (biometric/PIN required)";
  if ((ad.flags & 0x10) && !(ad.flags & 0x08)) return "invalid credential backup flags";
  return null;
}

export function coseToJwk(cose: Map<number, unknown>): JsonWebKey {
  // kty 2 (EC2), alg -7 (ES256), crv 1 (P-256)
  if (cose.get(1) !== 2 || cose.get(3) !== -7 || cose.get(-1) !== 1) throw new Error("only ES256/P-256 passkeys are supported");
  if (![cose.get(-2), cose.get(-3)].every(value => Buffer.isBuffer(value) && value.length === 32)) throw new Error("invalid P-256 coordinates");
  return { kty: "EC", crv: "P-256", x: b64u(cose.get(-2) as Buffer), y: b64u(cose.get(-3) as Buffer) };
}

export async function registerPasskey(store: EventStore, actor: Actor, body: Record<string, unknown>, cfg = passkeyConfig()) {
  if (actor.role !== "leader" || actor.channel !== "device") return { ok: false as const, reason: "only the leader can enrol a passkey" };
  const existing = credentials(await store.all(), actor.participant.id);
  // First enrolment needs a fresh step-up (demo code); later enrolments need a fresh PASSKEY step-up.
  if (!actor.stepUpFresh) return { ok: false as const, reason: existing.length ? "unlock with your existing passkey first" : "verify with the one-time leader code first" };
  const clientData = fromB64u(body.clientDataJSON);
  const cd = checkClientData(clientData, "webauthn.create", cfg);
  if (!cd.ok) return { ok: false as const, reason: cd.reason };
  if (!(await consumeChallenge(store, actor.sessionId, "register", cd.challenge))) return { ok: false as const, reason: "challenge invalid, expired or reused" };
  let ad: AuthData;
  try {
    const att = decodeCbor(fromB64u(body.attestationObject)).value;
    if (!(att instanceof Map) || att.get("fmt") !== "none" || !(att.get("attStmt") instanceof Map) || att.get("attStmt").size !== 0)
      throw new Error("unsupported attestation");
    ad = parseAuthData(att.get("authData"));
  } catch { return { ok: false as const, reason: "invalid or unsupported attestationObject" }; }
  const err = checkAuthData(ad, cfg);
  if (err) return { ok: false as const, reason: err };
  if (!ad.credentialId || !ad.cose) return { ok: false as const, reason: "no credential in attestation" };
  let jwk: JsonWebKey;
  try { jwk = coseToJwk(ad.cose); createPublicKey({ key: jwk, format: "jwk" }); } catch { return { ok: false as const, reason: "invalid credential key" }; }
  const cred: StoredCredential = { participantId: actor.participant.id, credentialId: b64u(ad.credentialId), jwk, signCount: ad.signCount, createdAt: new Date().toISOString() };
  type Registration = { ok: true; credentialId: string } | { ok: false; reason: string };
  const result = await store.appendGuarded<Registration>((events) => {
    const up = latestStepUp(events, actor.sessionId);
    const enrolled = credentials(events, actor.participant.id);
    if (!up || Date.parse(up.expiresAt) <= Date.now() || (enrolled.length > 0 && up.method !== "passkey"))
      return { reject: { ok: false, reason: "fresh verification with the enrolled passkey is required" } };
    if (credentials(events).some(c => c.credentialId === cred.credentialId))
      return { reject: { ok: false, reason: "credential is already enrolled" } };
    return { append: ev("passkey", cred.credentialId, cred), result: { ok: true, credentialId: cred.credentialId } };
  });
  if (!result.ok) return result;
  const stored = credentials(await store.all(), actor.participant.id).find(c => c.credentialId === cred.credentialId);
  return stored && stored.jwk.x === jwk.x && stored.jwk.y === jwk.y ? result : { ok: false as const, reason: "credential read-back failed" };
}

export async function assertPasskey(store: EventStore, actor: Actor, body: Record<string, unknown>, cfg = passkeyConfig()) {
  if (actor.role !== "leader" || actor.channel !== "device") return { ok: false as const, reason: "only the leader can unlock the Leader Desk" };
  const cred = credentials(await store.all(), actor.participant.id).find((c) => c.credentialId === String(body.credentialId ?? ""));
  if (!cred) return { ok: false as const, reason: "this device's passkey is not enrolled for the leader" };
  const clientData = fromB64u(body.clientDataJSON);
  const cd = checkClientData(clientData, "webauthn.get", cfg);
  if (!cd.ok) return { ok: false as const, reason: cd.reason };
  if (!(await consumeChallenge(store, actor.sessionId, "assert", cd.challenge))) return { ok: false as const, reason: "challenge invalid, expired or reused" };
  const authData = fromB64u(body.authenticatorData);
  let ad: AuthData;
  try { ad = parseAuthData(authData); } catch { return { ok: false as const, reason: "invalid authenticator data" }; }
  const err = checkAuthData(ad, cfg);
  if (err) return { ok: false as const, reason: err };
  const signed = Buffer.concat([authData, sha256(clientData)]);
  try {
    const key = createPublicKey({ key: cred.jwk, format: "jwk" });
    if (!cryptoVerify("sha256", signed, { key, dsaEncoding: "der" }, fromB64u(body.signature))) return { ok: false as const, reason: "signature invalid" };
  } catch { return { ok: false as const, reason: "signature invalid" }; }
  const expiresAt = new Date(Date.now() + 10 * 60_000).toISOString();
  type Assertion = { ok: true; expiresAt: string } | { ok: false; reason: string };
  const result = await store.appendGuarded<Assertion>((events) => {
    const latest = credentials(events, actor.participant.id).find(c => c.credentialId === cred.credentialId);
    if (!latest || ((ad.signCount > 0 || latest.signCount > 0) && ad.signCount <= latest.signCount))
      return { reject: { ok: false, reason: "sign counter did not increase (possible cloned key)" } };
    return { append: ev("passkey_verified", actor.sessionId, { credential: { ...latest, signCount: ad.signCount }, stepUp: { method: "passkey", expiresAt } }), result: { ok: true, expiresAt } };
  });
  if (!result.ok) return result;
  const up = latestStepUp(await store.all(), actor.sessionId);
  return up?.method === "passkey" && up.expiresAt === expiresAt ? result : { ok: false as const, reason: "passkey step-up read-back failed" };
}

// ---------------------------------------------------------------- minimal CBOR (decode)
export function decodeCbor(buf: Buffer, pos = 0, depth = 0): { value: unknown; end: number } {
  if (depth > 16 || pos >= buf.length) throw new Error("invalid CBOR nesting or length");
  const ib = buf[pos++];
  const major = ib >> 5;
  let info = ib & 0x1f;
  let len: number;
  if (info < 24) len = info;
  else if (info === 24) len = buf[pos++];
  else if (info === 25) { len = buf.readUInt16BE(pos); pos += 2; }
  else if (info === 26) { len = buf.readUInt32BE(pos); pos += 4; }
  else throw new Error("unsupported CBOR length");
  if (!Number.isSafeInteger(len) || len < 0 || len > 16384 || pos > buf.length) throw new Error("CBOR length exceeds input limit");
  if ((major === 2 || major === 3) && pos + len > buf.length) throw new Error("truncated CBOR bytes");
  switch (major) {
    case 0: return { value: len, end: pos };
    case 1: return { value: -1 - len, end: pos };
    case 2: return { value: buf.subarray(pos, pos + len), end: pos + len };
    case 3: return { value: buf.subarray(pos, pos + len).toString("utf8"), end: pos + len };
    case 4: { const a: unknown[] = []; for (let i = 0; i < len; i++) { const r = decodeCbor(buf, pos, depth + 1); a.push(r.value); pos = r.end; } return { value: a, end: pos }; }
    case 5: { const m = new Map<unknown, unknown>(); for (let i = 0; i < len; i++) { const k = decodeCbor(buf, pos, depth + 1); const v = decodeCbor(buf, k.end, depth + 1); if (m.has(k.value)) throw new Error("duplicate CBOR key"); m.set(k.value, v.value); pos = v.end; } return { value: m, end: pos }; }
    case 7: info = len; return { value: info === 20 ? false : info === 21 ? true : null, end: pos };
    default: throw new Error("unsupported CBOR type");
  }
}

